import{_ as t,c as e,a2 as a,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第二十二章 没有谁可以逃过死亡","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/22第二十二章 没有谁可以逃过死亡.md","filePath":"meditation/巴利文大藏经/22第二十二章 没有谁可以逃过死亡.md"}'),_={name:"meditation/巴利文大藏经/22第二十二章 没有谁可以逃过死亡.md"};function r(n,p,i,s,d,c){return o(),e("div",null,p[0]||(p[0]=[a('<h1 id="第二十二章-没有谁可以逃过死亡" tabindex="-1">第二十二章 没有谁可以逃过死亡 <a class="header-anchor" href="#第二十二章-没有谁可以逃过死亡" aria-label="Permalink to &quot;第二十二章 没有谁可以逃过死亡&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部3相应22经/祖母经(憍萨罗相应/有偈篇/祇夜)</p><p>有个时候，骄萨罗国的波斯匿王来到佛陀的住所，顶礼佛陀后，波斯匿王在一旁坐下，佛陀对波斯匿王说：“大王，你为什么脸上挂着泪珠？发生了什么事情？你从何而来？”</p><p>波斯匿王回答：“世尊，我慈祥的老祖母过世了，我正在王宫为老祖母举行丧礼，每当我想到老祖母在世时对我无微不至的关怀和慈爱，我就忍不住泪流满面，虽然我的老祖母已经一百二十岁了，在别人的眼中，她已经是福寿双全了，可是到现在为止我还是无法接受老祖母已经离我而去的事实。</p><p>世尊，如果可能的话，我愿意用我所有的大象军团去换取老祖母不要离世，去换取老祖母长生不老、万寿无疆。</p><p>世尊，如果可能的话，我愿意用我所有的骑兵军团去换取老祖母不要离世，去换取老祖母长生不老、万寿无疆。</p><p>世尊，如果可能的话，我愿意用我所有的村庄、城市、国土去换取老祖母不要离世，去换取老祖母长生不老、万寿无疆。”</p><p>佛陀说：“大王，请你节哀顺变，大王，世间一切的人或众生最终都会死去，没有哪一个人或众生是可以逃过死亡的。大王，有生就有死，无生就无死，要想不死就要不生。”</p><p>波斯匿王说：“世尊，这个道理您在过去曾经教导过我，您曾经对我说：世间一切的人或众生最后都会死去，没有谁是可以超越死亡的，就算是已经证悟解脱果位的修行人，他们在世间的这个身体也是脆弱不堪的，他们也只有在不挂念和执着这个在世间的身体后，才能最终从生死的轮回中永远的解脱出来。”</p><p>佛陀说：“大王，确实是这样的，出生在世间的人或众生，没有哪一个是可以免除死亡的。没有哪一个是可以超越死亡的。他们最终全部都会死去。大王，就犹如陶匠烧制出来的陶瓷器具，它们最终都是会被打碎的，就算是放置时间再久的陶瓷器具，最终也是会破碎的。没有哪一件陶瓷器具是可以永远不破碎，不破裂的。大王，同样的道理，世间的一切人或众生最终也是要死去的，没有谁是可以免除死亡的，没有谁是可以超越死亡的。</p><p>大王，世间的一切人或众生最后都将死去，因为有生就必有死，要想不死就要不生，不生就不死。这些死去的人或众生他们依靠在世间种植出来的福德，造下的罪业投生到不同的地方去，做恶事造下罪业的人或众生投生到不好的地方，做善事种植了很多福德的人或众生投生到好的地方，所以一切在世的人或众生都应该多做善事，不做恶事，以此为自己的未来世积聚福德，因为福德的多少决定了未来世投生的地方和类别。福德深厚的人或众生投生到富贵之家，上生到天界享福，甚至于从生死轮回中永远的解脱出来。福德薄弱、罪业深重的人或众生，投生到贫贱之家，下堕到地狱、饿鬼、畜生三恶道受苦。”</p><p>这时，佛陀说偈言：</p><p>「众生皆必死，生者无不死。</p><p>应如依其业，随行功罪果。</p><p>依恶堕地狱，功德生天界。</p><p>然者行善事，积善为未来。</p><p>功德实众人，后世渡津场。」</p>',18)]))}const f=t(_,[["render",r]]);export{m as __pageData,f as default};
